#include <cassert>
#include <cstdio>
#include <vector>
#include "safeseat_pose_anomaly.hpp"
#include "safeseat_temporal_filter.hpp"
#include "frame_quality.hpp"
static dl::detect::result_t make_pose(bool nose=true,bool left_eye=false,bool right_eye=false){dl::detect::result_t p;p.box={74,63,182,234};p.keypoint.assign(34,0);p.score=.5f;if(nose){p.keypoint[0]=142;p.keypoint[1]=100;}if(left_eye){p.keypoint[2]=146;p.keypoint[3]=96;}if(right_eye){p.keypoint[4]=136;p.keypoint[5]=96;}p.keypoint[10]=164;p.keypoint[11]=136;p.keypoint[12]=108;p.keypoint[13]=138;return p;}
int main(){float f[7]={};auto p=make_pose(true,false,false);assert(safeseat_extract_pose_features(p,320,240,f));p=make_pose(false,true,true);assert(!safeseat_extract_pose_features(p,320,240,f));SafeSeatTemporalFilter tf;auto s=tf.update(true,SafeSeatPoseState::NORMAL);assert(s.state==SafeSeatFilteredState::NORMAL);s=tf.update(true,SafeSeatPoseState::DEVIATION_STRONG);assert(s.state==SafeSeatFilteredState::DEVIATION_PENDING);s=tf.update(true,SafeSeatPoseState::NORMAL);assert(s.state==SafeSeatFilteredState::NORMAL&&!s.confirmed_deviation);tf.reset();s=tf.update(true,SafeSeatPoseState::DEVIATION_STRONG);s=tf.update(false,SafeSeatPoseState::UNKNOWN);s=tf.update(true,SafeSeatPoseState::DEVIATION_MODERATE);assert(s.state==SafeSeatFilteredState::DEVIATION_CONFIRMED);s=tf.update(true,SafeSeatPoseState::NORMAL);assert(s.state==SafeSeatFilteredState::DEVIATION_CONFIRMED);s=tf.update(true,SafeSeatPoseState::NORMAL);assert(s.state==SafeSeatFilteredState::NORMAL);constexpr int W=32,H=32;std::vector<unsigned char> flat(W*H*3,128),checker(W*H*3);for(int y=0;y<H;y++)for(int x=0;x<W;x++){unsigned char v=((x/2+y/2)&1)?255:0;for(int c=0;c<3;c++)checker[3*(y*W+x)+c]=v;}assert(safeseat_rgb888_sharpness(checker.data(),W,H)>safeseat_rgb888_sharpness(flat.data(),W,H)+1000.0f);std::puts("V4 structural tests PASS");}
